/**
 * 🏹 Flecha / Ballesta cinemática con voxelesUI, estela de vuelo y física balística.
 *
 * - Lanzamiento desde la mano (perspectiva FPS) hacia el centro de la mira.
 * - Detección real de impacto contra agentes articulados (game.esqueletos), NPCs (mc.agents) y bloques.
 * - Si impacta a un agente a cualquier distancia: salpica sangre, empuja al objetivo y avisa con toast.
 * - Si impacta contra un bloque con 'alRomper' (ej. TNT): lo rompe y detona su acción.
 * - En bloques normales: estallido de chispas y queda clavada en el ángulo de impacto.
 */
(async function () {
  'use strict';

  // Partículas para el impacto y sangre
  let chispas = null;
  let sangre = null;
  try {
    const P = await game.snippet('particulas-voxel');
    chispas = P.crea({
      grupo: 'flecha_impacto',
      chorro: 14,
      fuerza: 2.8,
      grav: 16,
      dura: 0.45,
      desvanece: 0.0,
      vuelo: 0.5,
      disperso: 0.15,
      hacia: 'radial',
      posarse: false,
      colores: [[1.0, 0.9, 0.4], [1.0, 0.6, 0.1], [0.8, 0.8, 0.85]]
    });

    sangre = (window.game && game.sangre) || P.crea({
      grupo: 'sangre',
      chorro: 22,
      dura: 25,
      desvanece: 4,
      grav: 24,
      fuerza: 1.8,
      rebote: 0.22,
      vuelo: 1,
      tope: 500,
      hacia: 'radial',
      colores: [[0.78, 0.08, 0.08], [0.66, 0.05, 0.05], [0.88, 0.15, 0.12], [0.55, 0.03, 0.03]]
    });
    if (window.game) game.sangre = sangre;
  } catch (e) {}

  const P_VOX = 16; // 16 voxeles finos por bloque de mundo
  const flechas = [];
  let animRaf = 0;
  let lastTime = 0;

  if (game.voxelesUI && game.voxelesUI.material) {
    game.voxelesUI.material('flechas', { emite: true, luz: 6 });
  }

  function lanzarFlecha(opciones = {}) {
    if (typeof mc === 'undefined' || !mc.pos || !mc.active) {
      if (typeof toast === 'function') toast('🏹 Abre el Mundo (🌍) primero');
      return;
    }

    const esc = (typeof mc.scale === 'number') ? mc.scale : 1;
    const oy = mc.pos[1] + ((typeof MC_EYE === 'number' ? MC_EYE : 1.62) * esc);
    const cp = Math.cos(mc.pitch || 0);
    const dirX = -Math.sin(mc.yaw || 0) * cp;
    const dirY = Math.sin(mc.pitch || 0);
    const dirZ = -Math.cos(mc.yaw || 0) * cp;

    const rightX = Math.cos(mc.yaw || 0);
    const rightZ = -Math.sin(mc.yaw || 0);

    const vel = (typeof opciones.velocidad === 'number') ? opciones.velocidad : 34;
    const grav = (typeof opciones.gravedad === 'number') ? opciones.gravedad : 9.8;

    const x0 = mc.pos[0] + dirX * 0.45 + rightX * (0.28 * esc);
    const y0 = oy + dirY * 0.45 - (0.16 * esc);
    const z0 = mc.pos[2] + dirZ * 0.45 + rightZ * (0.28 * esc);

    const targetDist = 32;
    const targetX = mc.pos[0] + dirX * targetDist;
    const targetY = oy + dirY * targetDist;
    const targetZ = mc.pos[2] + dirZ * targetDist;
    const toTargetDist = Math.hypot(targetX - x0, targetY - y0, targetZ - z0) || 1;
    const vx = ((targetX - x0) / toTargetDist) * vel;
    const vy = ((targetY - y0) / toTargetDist) * vel;
    const vz = ((targetZ - z0) / toTargetDist) * vel;

    flechas.push({
      id: Math.random().toString(36).slice(2),
      origen: [mc.pos[0], oy, mc.pos[2]],
      x: x0,
      y: y0,
      z: z0,
      vx: vx,
      vy: vy,
      vz: vz,
      dirX: dirX,
      dirY: dirY,
      dirZ: dirZ,
      grav: grav,
      clavada: false,
      tiempoClavada: 0,
      vidaMax: 5.0,
      longitud: 12,
      estela: []
    });

    if (!animRaf) {
      lastTime = performance.now();
      animRaf = requestAnimationFrame(bucleFlechas);
    }
  }

  function bucleFlechas(ahora) {
    const dt = Math.min(0.05, (ahora - lastTime) / 1000);
    lastTime = ahora;

    if (game.voxelesUI) {
      game.voxelesUI.limpia('flechas');
    }

    const T_VOX = 1 / P_VOX;

    for (let i = flechas.length - 1; i >= 0; i--) {
      const f = flechas[i];

      if (f.clavada) {
        f.tiempoClavada += dt;
        if (f.tiempoClavada >= f.vidaMax) {
          flechas.splice(i, 1);
          continue;
        }
      } else {
        f.vy -= f.grav * dt;
        const nx = f.x + f.vx * dt;
        const ny = f.y + f.vy * dt;
        const nz = f.z + f.vz * dt;

        const vMod = Math.hypot(f.vx, f.vy, f.vz);
        if (vMod > 0.001) {
          f.dirX = f.vx / vMod;
          f.dirY = f.vy / vMod;
          f.dirZ = f.vz / vMod;
        }

        f.estela.unshift([f.x, f.y, f.z]);
        if (f.estela.length > 6) f.estela.pop();

        const distPaso = Math.hypot(nx - f.x, ny - f.y, nz - f.z);
        const subPasos = Math.max(1, Math.ceil(distPaso / 0.20));
        let choco = false;
        let hitX = nx, hitY = ny, hitZ = nz;
        let hitCell = null;
        let hitEsqueleto = null;
        let hitAgente = null;

        for (let s = 1; s <= subPasos; s++) {
          const t = s / subPasos;
          const testX = f.x + (nx - f.x) * t;
          const testY = f.y + (ny - f.y) * t;
          const testZ = f.z + (nz - f.z) * t;

          // 1. Colisión contra Agentes Articulados (esqueletos/zombies)
          if (typeof game !== 'undefined' && game.esqueletos && typeof game.esqueletos.enPunto === 'function') {
            const esq = game.esqueletos.enPunto(testX, testY, testZ);
            if (esq) {
              choco = true;
              hitEsqueleto = esq;
              hitX = testX; hitY = testY; hitZ = testZ;
              break;
            }
          }

          // 2. Colisión contra NPCs cúbicos (mc.agents)
          if (typeof mc !== 'undefined' && mc.agents) {
            for (const ag of mc.agents.values()) {
              const d = Math.hypot(ag.x - testX, (ag.y + 0.5) - testY, ag.z - testZ);
              if (d <= 0.75) {
                choco = true;
                hitAgente = ag;
                hitX = testX; hitY = testY; hitZ = testZ;
                break;
              }
            }
            if (choco) break;
          }

          // 3. Colisión contra bloques del terreno
          const bx = Math.floor(testX), by = Math.floor(testY), bz = Math.floor(testZ);
          if (typeof mcInside === 'function' && mcInside(bx, by, bz)) {
            const id = (mc.grid && mc.grid[mcIdx(bx, by, bz)]) || 0;
            if (id !== 0 && !(typeof mcIsCellReplaceable === 'function' && mcIsCellReplaceable(bx, by, bz))) {
              choco = true;
              hitX = testX; hitY = testY; hitZ = testZ;
              hitCell = [bx, by, bz];
              break;
            }
          }
        }

        if (choco) {
          const distTotal = Math.hypot(hitX - f.origen[0], hitZ - f.origen[2]).toFixed(1);

          if (hitEsqueleto) {
            // Impacto sobre agente articulado
            if (sangre) sangre.salpica(hitEsqueleto.punto || [hitX, hitY, hitZ]);
            if (typeof game.esqueletos.empujar === 'function') {
              game.esqueletos.empujar(hitEsqueleto.id || hitEsqueleto.rig, 10, f.dirX, f.dirZ);
            }
            if (typeof toast === 'function') {
              const nombre = hitEsqueleto.texto || hitEsqueleto.nombre || 'agente';
              toast('🎯 ¡Diana! Flechazo a ' + nombre + ' a ' + distTotal + 'm');
            }
            flechas.splice(i, 1);
            continue;
          } else if (hitAgente) {
            // Impacto sobre NPC cúbico
            if (sangre) sangre.salpica([hitX, hitY, hitZ]);
            if (typeof toast === 'function') {
              toast('🎯 ¡Diana! Flechazo a ' + (hitAgente.name || hitAgente.id) + ' a ' + distTotal + 'm');
            }
            flechas.splice(i, 1);
            continue;
          } else if (hitCell) {
            // Impacto sobre bloque del terreno
            if (chispas) chispas.salpica([hitX, hitY, hitZ], 14);

            let avisaRotura = null;
            if (typeof game !== 'undefined' && game.bloques && typeof game.bloques.avisoDeRotura === 'function') {
              avisaRotura = game.bloques.avisoDeRotura(hitCell[0], hitCell[1], hitCell[2]);
            }

            if (avisaRotura) {
              if (typeof setVoxel === 'function') setVoxel(hitCell[0], hitCell[1], hitCell[2], 0);
              avisaRotura();
              flechas.splice(i, 1);
              continue;
            } else {
              f.x = hitX; f.y = hitY; f.z = hitZ;
              f.vx = 0; f.vy = 0; f.vz = 0;
              f.clavada = true;
              f.tiempoClavada = 0;
              f.estela = [];
            }
          }
        } else {
          f.x = nx; f.y = ny; f.z = nz;
        }
      }

      // Dibujar en capa voxelesUI
      if (game.voxelesUI) {
        const dx = f.dirX * T_VOX, dy = f.dirY * T_VOX, dz = f.dirZ * T_VOX;
        const colPunta = [1.0, 1.0, 1.0];
        const colCuerpo = [0.65, 0.44, 0.22];
        const colPluma1 = [0.95, 0.25, 0.18];
        const colPluma2 = [0.95, 0.95, 0.95];
        const colEstela = [0.85, 0.92, 1.0];

        if (!f.clavada && f.estela) {
          for (let eIdx = 0; eIdx < f.estela.length; eIdx++) {
            const ep = f.estela[eIdx];
            game.voxelesUI.pon(Math.floor(ep[0] * P_VOX), Math.floor(ep[1] * P_VOX), Math.floor(ep[2] * P_VOX), colEstela, 'flechas');
          }
        }

        for (let seg = 0; seg < f.longitud; seg++) {
          const px = f.x - dx * seg, py = f.y - dy * seg, pz = f.z - dz * seg;
          let col = colCuerpo;
          if (seg === 0) col = colPunta;
          else if (seg === f.longitud - 2) col = colPluma1;
          else if (seg === f.longitud - 1) col = colPluma2;
          game.voxelesUI.pon(Math.floor(px * P_VOX), Math.floor(py * P_VOX), Math.floor(pz * P_VOX), col, 'flechas');
        }
      }
    }

    if (flechas.length > 0) {
      animRaf = requestAnimationFrame(bucleFlechas);
    } else {
      animRaf = 0;
      if (game.voxelesUI) game.voxelesUI.limpia('flechas');
    }
  }

  game.onKey('q', () => { lanzarFlecha(); });
  game.dispararFlecha = lanzarFlecha;
  window.lanzarFlecha = lanzarFlecha;

  console.log('🏹 [Flecha-Arco] Snippet cargado con detección balística de agentes.');
  return { lanzarFlecha, flechas };
})();
